<?php $current = max( 1, min( 7, (int) ( $args['model']['current_step'] ?? 1 ) ) ); $steps = array( 'خوش‌آمد و ساخت رمز', 'اطلاعات شخصی', 'اتصال Google', 'زمان‌های در دسترس', 'بازبینی آمادگی', 'تور راهنمای پرتال', 'پایان' ); ?>
<section class="dzn-tp-section" aria-labelledby="tp-onboarding"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">داستان‌نمای شروع همکاری</p><h2 id="tp-onboarding">هفت گام آمادگی</h2></div><span>گام <?php echo esc_html( $current ); ?> از ۷</span></div><ol class="dzn-tp-onboarding"><?php foreach ( $steps as $index => $step ) : ?><li class="<?php echo esc_attr( $index + 1 < $current ? 'is-complete' : ( $index + 1 === $current ? 'is-current' : 'is-future' ) ); ?>"><?php echo esc_html( $step ); ?></li><?php endforeach; ?></ol><h3>چک‌لیست آمادگی</h3><div class="dzn-tp-checklist"><?php foreach ( array( 'می‌دانم چگونه کلاس را شروع کنم', 'می‌دانم چگونه از طریق WhatsApp با هنرجو تماس بگیرم', 'می‌دانم چگونه Google Meet اضطراری بسازم', 'میکروفن و دوربین آماده‌اند', 'Google Meet برای موسیقی تنظیم شده است' ) as $item ) : ?><label><input type="checkbox"> <?php echo esc_html( $item ); ?></label><?php endforeach; ?></div><button class="dzn-button" type="button" data-dzn-tp-presentation>ادامه در آینده</button><p class="dzn-tp-action-status" aria-live="polite"></p><p class="dzn-tp-help">این مسیر دعوت، حساب یا آمادگی معتبر ایجاد نمی‌کند.</p></section>
